for index, language in enumerate(['en', 'ja']):
    def quote(text):
        return '"' + text.replace('\\', '\\\\').replace('"', '\\"').replace('\n', '\\n') + '"'
    output = '\n'.join(f'{quote(key)} = {quote(pair[index])};' for key, pair in sorted(strings.items())) + '\n'
    Path(f'Sources/OpenLadderStudio/Resources/{language}.lproj/Localizable.strings').write_text(output)
print(f'{len(strings)} keys in English and Japanese')
